from executa_sdk import CredentialsClient, CredentialsError, CREDENTIALS_ERR_NOT_GRANTED

creds = CredentialsClient()

async def gmail_token(account: str | None = None) -> dict:
    """`account` is the platform-injected multi_account argument (email or id)."""
    account_id = account
    if account and "@" in account:  # resolve email → account_id
        listing = await creds.list_accounts(provider="google")
        match = [a for a in listing["accounts"] if (a["email"] or "").lower() == account.lower()]
        if not match:
            return {"error": f"no account {account!r}", "available": [a["email"] for a in listing["accounts"]]}
        account_id = match[0]["account_id"]
    try:
        tok = await creds.get_token(provider="google", account_id=account_id)
    except CredentialsError as e:
        if e.code == CREDENTIALS_ERR_NOT_GRANTED:
            return {"error": "reconnect required", "detail": e.message}
        raise
    # use tok["access_token"] against the Gmail API — never log it unmasked
    return {"account_id": tok["account_id"], "expires_at": tok["expires_at"]}
